"""Report actual task and failure changes, with explicit novelty boundaries."""
import json,csv
from pathlib import Path
from collections import Counter
from scripts.run_material_partial_consensus_v16 import configuration,METHODS,FAMILIES
from scripts.run_textured_material_comparison_v1 import save


def table(headers,rows):
    return '\n'.join(['|'+'|'.join(headers)+'|','|'+'|'.join(['---']*len(headers))+'|']+['|'+'|'.join(str(x) for x in row)+'|' for row in rows])


def main():
    c=configuration();root=Path(c['output']);s=json.loads((root/'scores.json').read_text(encoding='utf-8'));d=json.loads((root/'diagnosis_summary.json').read_text(encoding='utf-8'));summary={(r['variant'],r['method']):r for r in s['summary']};variants=c['variants'];oracle=list(csv.DictReader((root/'oracle_by_family.csv').open(encoding='utf-8-sig')));fail=list(csv.DictReader((root/'failure_attribution.csv').open(encoding='utf-8-sig')));seeds=list(csv.DictReader((root/'rich_local_seed_diagnosis.csv').open(encoding='utf-8-sig')))
    lines=['# V16：局部、可拒绝共识的完整任务结果','','## 本轮实际完成','','冻结V3学习字段，四外观×24资产×8方法，共768条任务；全部预测封存后才进行材料真值评分。每族每方向最多12种子、3刚体更新，局部三点的TLS与partial逐字节共用初始位姿。保留所有V15联合端点和原有限身份搜索图。无新训练、数据或参数扫描。','','## 完整任务','','数字为身份均正确且三段固定历史材料锚点误差均≤5cm的资产数；每列24项。', '', table(['方法']+variants,[[m]+[summary[v,m]['qualified'] for v in variants] for m in METHODS]),'','背面子集每列8项：','',table(['方法']+variants,[[m]+[summary[v,m]['rear_qualified'] for v in variants] for m in METHODS]),'','前四行为旧结果重放/共同池头；最后四行为“旧池＋该生成族”的消融，不声称八方法候选池相同。普通TLS本身已可拒绝外点。','','## 生成上限与实际选择','','真值仅用于事后读取正确身份的池内最低材料锚点误差；候选合格不等于推断成功。','']
    names=['retained']+FAMILIES+['union'];lines += [table(['候选范围']+variants,[[name]+[sum(r['variant']==v and r[name+'_error_m'] not in ['', 'None'] and float(r[name+'_error_m'])<=.05 for r in oracle) for v in variants] for name in names]),'','## 同资产的增减','','新增与丢失同时列出；四外观相关，不能把768条方法记录当独立样本量。','',table(['外观','对照→候选','新增资产','丢失资产','共同正确ID误差变化中位数(m)'],[[r['variant'],r['baseline']+'→'+r['candidate'],r['gained'],r['lost'],r['paired_worst_error_change_median_m']] for r in s['comparisons']]),'','## 主共同评分的失败归因','']
    counts=Counter((r['variant'],r['category']) for r in fail if r['method']=='common_point_density');cats=sorted({cat for _,cat in counts});lines += [table(['类别']+variants,[[cat]+[counts[v,cat] for v in variants] for cat in cats]),'','## rich背面H2配对诊断','','下表为GT选择的8个真实身份配对，5cm配对误差，不是完整三段任务，不进入预测。','',table(['生成族','raw合格配对/8','前3位姿合并双向后合格配对/8'],[[f,d['rear_pair_summary'][f+'_raw_qualified'],d['rear_pair_summary'][f+'_selected_qualified']] for f in FAMILIES]),'',f"原global种子真实材料峰{d['global_true_peak_seeds']}；local种子真实材料峰{d['local_true_peak_seeds']}。局部同起点共有{d['local_seed_count']}个，初始化/普通TLS/partial达到5cm的种子分别为{d['initial_qualified']}/{d['tls_qualified']}/{d['partial_qualified']}。这不是全seed上限，也不是超预算新方法。",'']
    bad=[r for r in seeds if float(r['partial_objective_drop'])>1e-10 and float(r['partial_error_m'])>float(r['initial_error_m'])+1e-8];lines += [f'混合目标下降但实际材料误差变大的局部种子：{len(bad)}/{len(seeds)}。该数字描述目标与任务不一致，不能解释为实现了更好匹配。','','## 解释边界与下一步','','局部归一化、三点SVD、TLS和Gaussian外点混合都是已知工具。本轮是分离失败机制的算法实验，不能把实现这些组件称为原创贡献。局部种子与局部权重仍作为一包改变；partial同时改变特征先验、空匹配和目标容量，也尚未拆出三者各自作用。','','空匹配只接收局部候选外质量，没有射线可见性或历史未知表面的物理建模。容量缩减不是精确EM/最优传输，接受检验仅保证原混合目标不升。若同起点普通TLS已解释收益，就保留为工程改进；若partial相对TLS没有新增合格或改善材料误差，就不继续扫该混合模型参数。','','判断需要同时看：实际任务增减、候选覆盖、raw→selected损失、同起点目标下降与真实误差变化。优先改阻断主线的对应或选择模型，不能用更多迭代替代原因分析。后续明确决策见本轮decision文件。','','## 已有发表方法参考','','V15官方PointDSC模块默认13/16/14/16；预先固定5cm阈值控制0/6/5/5。保留较强默认结果，不能择弱报告。输入为我们的冻结描述子NN和固定任务身份图，不是作者完整FCGF系统，也不是与V16同候选/同生成预算控制。','','[MAC（CVPR 2023）](https://openaccess.thecvf.com/content/CVPR2023/html/Zhang_3D_Registration_With_Maximal_Cliques_CVPR_2023_paper.html)已研究局部极大团可能优于最大团；[CPD](https://arxiv.org/abs/0905.2635)已有概率混合配准。没有独立数据及强先例排除，不能确认高创新。','','## 正确性与局限','',f"72项合成数学正确性核对通过；本轮完整评分核对{s['checks']}项，源中心验证{s['source_centers_verified']}个，同起点核验{s['identical_triplet_starts_verified']}组、目标不升路径{s['monotone_paths_verified']}条，选中目标函数最大重算差{s['max_selected_objective_error']}。这些是实现完整性，不是独立重跑确认。",'','一个已见TRAIN场景、四相关外观；有限身份图仍可能不访问真实身份。无实机或真实跨期确认。旧192项结果和旧源码/权重通过完成审计另行核验。']
    histogram=Counter(int(r['true_pool_sources']) for r in seeds);lines += ['','## 进一步定位：局部池没有形成足够真对应','',f"96个rich背面正向局部池的真实材料源点数分布：{dict(sorted(histogram.items()))}；达到3个真源点的池为{d['local_pools_at_least3_true_sources']}。材料真对应标准为1.5cm；这不是一般可观测性或所有近似姿态不可能的证明。它与实际全部raw配对失败共同支持：目前主瓶颈在共识形成之前，不能只改最后top3裁剪或继续迭代。",'',f"目标容量缩减在{d['capacity_active_seeds']}/{d['local_seed_count']}个终点实际触发；故不能用‘容量没起作用’解释零增益。混合模型还存在可解析的软模态平均偏差：无噪声20mm双模态反例中，TLS保持真位姿而partial从真位姿漂移9.847mm；见模型文档。反例不是对真实任务38例漂移的唯一原因认定。",'','一次诊断CSV输出因前向/背面行列集合不同而失败，失败CSV及源码快照保留；补齐可选列后重跑诊断和报告。冻结推断、主评分及参数未改变。这是导出工程问题，不是算法收益。']
    report=Path('research/material_partial_consensus_results_v16_2026-10-27.md');report.write_text('\n'.join(lines)+'\n',encoding='utf-8');save(root/'report_facts.json',dict(objective_descent_but_material_error_worse=len(bad),diagnostic_seeds=len(seeds),true_pool_sources_histogram=dict(histogram),capacity_active_seeds=d['capacity_active_seeds']));print(report)


if __name__=='__main__':main()
